{
  "state": {"alert": "p99 latency 4s on orders-db since 14:02", "last_deploy": "orders-api v212 at 13:58"},
  "questions": {
    "system": {"type": "choice", "instructions": "Which system is failing?",
               "options": {"database": "", "api": "", "network": ""}},
    "db_owner": {"type": "text", "instructions": "Which team owns the database?",
                 "when": {"@system": "database"}},
    "page_oncall": {"type": "noul", "instructions": "Page the on-call engineer?",
                    "depends_on": ["db_owner"]},
    "deployment_related": {"type": "noul", "instructions": "Did a recent deployment cause it?",
                           "when": {"@system": "api"}}
  }
}
